CREATE TABLE users (id char(36) primary key,email varchar(255) not null unique,password_hash varchar(255) not null,active boolean not null default true) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE tenants (id char(36) primary key,name varchar(255) not null) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE memberships (tenant_id char(36),user_id char(36),role varchar(16) not null,primary key(tenant_id,user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE projects (id char(36) primary key,tenant_id char(36) not null,name varchar(255) not null,account_id varchar(100) not null default '',policy json,policy_version int not null default 0,reserved decimal(20,4) not null default 0,created_at datetime default current_timestamp,index(tenant_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE files (id char(36) primary key,tenant_id char(36) not null,project_id char(36) not null,name varchar(512) not null,kind varchar(20) not null,sha256 char(64) not null,storage_path varchar(512) not null,inspection json not null,mapping json,created_at datetime default current_timestamp,index(project_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE history (tenant_id char(36) not null,project_id char(36) not null,account_id varchar(100) not null,ad_id varchar(100) not null,data json not null,primary key(project_id,ad_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE drafts (id char(36) primary key,tenant_id char(36) not null,project_id char(36) not null,version int not null,data json not null,created_at datetime default current_timestamp,index(project_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE connections (tenant_id char(36) primary key,state json not null,tools json not null default (JSON_ARRAY()),bindings json not null default (JSON_OBJECT()),verified boolean not null default false) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE runs (id char(36) primary key,tenant_id char(36) not null,project_id char(36) not null,draft_id char(36) not null,draft_version int not null,policy_version int not null,status varchar(30) not null,frozen json not null,error text,cancelled boolean not null default false,created_at datetime default current_timestamp,unique(draft_id,draft_version)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE deployments (tenant_id char(36) not null,project_id char(36) not null,fingerprint char(64) not null,run_id char(36) not null,requirement json not null,status varchar(30) not null default 'pending',steps json not null default (JSON_OBJECT()),primary key(project_id,fingerprint)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE messages (id bigint auto_increment primary key,tenant_id char(36) not null,project_id char(36) not null,role varchar(30) not null,content longtext not null,created_at datetime default current_timestamp,index(project_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE mapping_templates (tenant_id char(36) not null,project_id char(36) not null,signature char(64) not null,data json not null,primary key(project_id,signature)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE audit (id bigint auto_increment primary key,tenant_id char(36) not null,project_id char(36),event varchar(100) not null,data json not null,created_at datetime default current_timestamp) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE jobs (id bigint auto_increment primary key,message json not null,status varchar(20) not null default 'pending',lease_until datetime,created_at datetime default current_timestamp,index(status,lease_until)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE intake_tasks (id char(36) primary key,tenant_id char(36) not null,project_id char(36) not null,draft_id char(36),version int not null,data json not null,created_at datetime default current_timestamp,index(project_id),unique(draft_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE project_contexts (project_id char(36) primary key,tenant_id char(36) not null,version int not null,data json not null) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
